solutionCode:
#include <stdio.h>

void minimoEMaximo(int v[], int n, int *min, int *max) {
    *min = v[0];
    *max = v[0];
    for (int i = 1; i < n; i++) {
        if (v[i] < *min) {
            *min = v[i];
        }
        if (*max < v[i]) {
            *max = v[i];
        }
    }
}
